public class Main {
	public static int euclidean(int x, int y) {
		int result = -1, z = 1;
		while (z > 0) {
			z = x % y;
			if (z == 0) result = y;
			x = y; y = z;
		}
		return result;
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int x = sc.nextInt();
		int y = sc.nextInt();
		if (y > x ) {
			int tmp = x; x = y; y = tmp;
		}
		int factor = euclidean(x, y);
		if (factor == -1) {
			System.out.println("not exist Greatest common factor");
		} else {
			System.out.println(euclidean(x, y));
		}
	}
}

import java.util.Scanner;

public class Main {

	public static void main(String[] atgs) {
		Scanner sc = new Scanner(System.in);
		int x = sc.nextInt();
		int y = sc.nextInt();
		int gcd = 0;
		if (x == y) {
			gcd = x;
		} else {
			gcd = calculation(x, y, gcd);
		}
		System.out.println(gcd);
		sc.close();
	}

	public static int calculation(int x, int y, int gcd) {
		if (x < y) {
			int tmp = x;
			x = y;
			y = tmp;
		}
		x %= y;
		for (int i = x; true; i--) {
			if (x % i == 0 && y % i == 0) {
				gcd = i;
				break;
			}
		}
		return gcd;
	}
}

