	public static int gcd(int x,int y){
		int r=0;
		if(x<y){
			swap(x,y);
		}
		while(y>0){
			r=x%y;
			x=y;
			y=r;
		}
		return x;
	}
	public static void swap(int x,int y){
		int dummy=y;
		y=x;
		x=dummy;
	}

	}

