            System.out.println("a == b");
        } 
    }

    public int[] splitIntChange(String str){
        String[] str_ = str.split(" ");
        int strlen = str_.length;
        int[] numarray = new int[strlen];

        for(int i = 0;i < strlen;i++){
            numarray[i] = Integer.parseInt(str_[i]); 
        }

        return numarray;
    }
}

