        int[][] y = new int[a[1]][a[2]];
        long[][] z = new long[a[0]][a[2]];
        for (int i = 0; i < a[0]; i++) {
            for (int j = 0; j < a[1]; j++) {
                x[i][j] = sc.nextInt();
            }
        }
        for (int i = 0; i < a[1]; i++) {
            for (int j = 0; j < a[2]; j++) {
                y[i][j] = sc.nextInt();
            }
        }

