    }
    static FastReader in = new FastReader();
    public static void main(String[] args) {
        int t = 1; //in.nextInt();
        while (t-- > 0)
            solve();
    }

    public static void solve() {

        int n = in.nextInt();
        HashSet<String> g = new HashSet();

        for(int i = 0; i < n; ++i){
            String t = in.nextLine();
            g.add(t);
        }
