        instance.solve();
    }

    private void solve() {
        try {
            int K = sc.nextInt();

            int sum = 0;

            for(int a=1; a<K+1; a++) {
                for(int b=1; b<K+1; b++) {
                    for(int c=1; c<K+1; c++) {

                        sum+=gcd(gcd(a,b),c);

                    }
                }
            }

            System.out.println(sum);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private int gcd(int m, int n) {
        int r;
        while (n > 0) {
            r = m % n;
            m = n;
            n = r;
        }
        return m;
    }

