	}

	public static long gcd (long a, long b, long c) {
		long temp;
		while((temp = a%b)!=0) {
			a = b;
			b = temp;
		}

		while((temp = c%b)!=0) {
			c = b;
			b = temp;
		}
		return b;
	}
}

