  public static int gcd(int x, int y){
    int big = Math.max(x,y);
    int small = Math.min(x,y);
    int surplus = big%small;
    if(surplus == 0){
      return small;
    }
    surplus = gcd(small,surplus);
    return surplus;
  }
}

