            a[i] = nextInt();
        }

        boolean[] ng = new boolean[N + 1];
        for(int i = 0;i < M;i++) {
            ng[a[i]] = true;
        }

        long[] dp = new long[N + 1];
        dp[0] = 1;
        for(int i = 0;i < N;i++) {
            if (ng[i]) continue;
            if (!ng[i + 1]){
                dp[i + 1] += dp[i];
                dp[i + 1] %= MOD;
            }
            if (i + 2 <= N && !ng[i + 2]) {
                dp[i + 2] += dp[i];
                dp[i + 2] %= MOD;
            }
        }

        out.println(dp[N]);
    }

