  public static long f(int N) {

    if (memo[N] > 0) {
      return memo[N];
    }

    if (N == 0) {
      return 0;
    }

    if (N == 1) {
      return 1;
    }

    long left = f(N-2);
    long right = f(N-1);

    return memo[N] = (left + right) % MOD;
