            && s.charAt(i) != 'G'
            && s.charAt(i) != 'T') {
                continue;
            }
            if (s.substring(i).matches("[ACGT]*")) {
                len = Math.max(len, s.substring(i).length());
            }
            for (int j = i + 1; j < s.length(); j++) {
                if (s.substring(i, j).matches("[ACGT]*")) {
                    len = Math.max(len, s.substring(i, j).length());
                }
            }
        }
        System.out.println(len);
        sc.close();
    }
}

