class Main {
  public static int getPalacePoint(int t, int aveT, List<Integer> hightList) {
    int point = 0;
    double pointT = 9999;
    for(int i = 0; i < hightList.size(); i++) {
      double targetTemperature = (t - (hightList.get(i) * 0.006));
      double diff = targetTemperature - aveT;
      if(diff < 0) {
        diff = -diff;
      }
      if(diff < pointT) {
