public class Main {
  private static int calculateDigitsSum(int i) {
    int sum = 0;
    while (i > 0) {
      sum += i % 10;
      i /= 10;
    }
    return sum;
  }

  private static int solve(int n, int a, int b) {
    int sum = 0;
    for (int i = 1; i <= n; i++) {
      int digitsSum = calculateDigitsSum(i);
      if (a <= digitsSum && digitsSum <= b) {
        sum += i;
      }
    }
    return sum;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int a = reader.nextInt();
    int b = reader.nextInt();
    out.println(solve(n, a, b));
  }

